CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),world_id uuid NOT NULL,actor_id uuid,name text NOT NULL,revision integer NOT NULL DEFAULT 1,FOREIGN KEY(owner_id,world_id) REFERENCES worlds(owner_id,id),FOREIGN KEY(owner_id,world_id,actor_id) REFERENCES world_characters(owner_id,world_id,id),UNIQUE(owner_id,id));
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,project_id uuid NOT NULL,title text NOT NULL,kind text NOT NULL CHECK(kind IN ('artifact','reference')),content text NOT NULL,content_hash text NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,project_id) REFERENCES projects(owner_id,id),UNIQUE(owner_id,id));
CREATE TABLE document_versions(owner_id uuid NOT NULL,document_id uuid NOT NULL,revision integer NOT NULL,content text NOT NULL,content_hash text NOT NULL,title text NOT NULL,asset_ids uuid[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(document_id,revision),FOREIGN KEY(owner_id,document_id) REFERENCES documents(owner_id,id));
CREATE TABLE document_assets(owner_id uuid NOT NULL,document_id uuid NOT NULL,asset_id uuid NOT NULL,PRIMARY KEY(document_id,asset_id),FOREIGN KEY(owner_id,document_id) REFERENCES documents(owner_id,id),FOREIGN KEY(owner_id,asset_id) REFERENCES assets(owner_id,id));
ALTER TABLE mcp_connections ADD COLUMN runtime text NOT NULL DEFAULT 'remote' CHECK(runtime IN ('remote','internal'));
CREATE UNIQUE INDEX one_internal_tools ON mcp_connections(owner_id) WHERE runtime='internal';

CREATE TABLE document_version_assets(owner_id uuid NOT NULL,document_id uuid NOT NULL,revision integer NOT NULL,asset_id uuid NOT NULL,PRIMARY KEY(document_id,revision,asset_id),FOREIGN KEY(document_id,revision) REFERENCES document_versions(document_id,revision),FOREIGN KEY(owner_id,asset_id) REFERENCES assets(owner_id,id));
